text=text[:start]+'''function editorialFigure(code,label){const a=presentation.visualSuccessor?.figures.find(x=>x.section===code);if(!a)return '';const width=a.width||1200,height=a.height||(code==='P03'?460:code==='P04'?240:420);return `<figure class="ef-editorial-figure ef-editorial-${code}" data-ef-figure="${code}"><div class="ef-figure-frame" style="aspect-ratio:${width}/${height}" role="group" aria-label="${esc(label)}"><img src="${esc(a.url)}" width="${width}" height="${height}" data-ef-figure-image="${code}" ${a.svgFallback?`data-ef-figure-fallback="${esc(a.svgFallback.url)}"`:''} alt="${esc(label)}" loading="lazy" decoding="async"></div><figcaption>${label}</figcaption></figure>`;}
'''.rstrip()+text[end:]
